      "arFull": "وَاَوْحَیْنَاۤ اِلٰی مُوْسٰۤی اَنْ اَسْرِ بِعِبَادِیْۤ اِنَّكُمْ مُّتَّبَعُوْنَ ۟",
      "ur": "اور ہم نے موسیٰ کو وحی کی کہ راتوں رات میرے بندوں کو نکال لے چل تم سب پیچھا کیے جاؤ گے.[1]",
      "en": "And We inspired to Moses, \"Travel by night with My servants; indeed, you will be pursued.\"",
      "footnotesUr": "[1] جب بلاد مصر میں حضرت موسیٰ (عليه السلام) کا قیام لمبا ہوگیا اور ہر طرح سےانہوں نے فرعون اور اس کے درباریوں پر حجت قائم کردی۔ لیکن اس کےباوجود وہ ایمان لانے پر تیار نہیں ہوئے، تو اب اس کے سوا کوئی چارہ نہیں رہ گیا تھا کہ انہیں عذاب و نکال سے دوچار کرکے سامان عبرت بنادیا جائے۔ چنانچہ اللہ تعالیٰ نے موسیٰ (عليه السلام) کو حکم دیا کہ راتوں رات بنی اسرائیل کو لے کر یہاں سے نکل جائیں، اور فرمایاکہ فرعون تمہارے پیچھے آئے گا، گھبرانا نہیں۔",
