      "ur": "اور جس دن کے لوگ دوباره جلائے جائیں مجھے رسوا نہ کر.[1]",
      "en": "And do not disgrace me on the Day they are [all] resurrected -",
      "footnotesUr": "[1] یعنی تمام مخلوق کے سامنے میرا مواخذہ کرکے یا عذاب سے دوچار کرکے حدیث میں آتا ہے کہ قیامت والے دن جب حضرت ابراہیم (عليه السلام) اپنے والد کو برے حال میں دیکھیں گے، تو ایک مرتبہ پھر اللہ کی بارگاہ میں ان کے لیے مغفرت کی درخواست کریں گے اورفرمائیں گے یا اللہ ! اس سے زیادہ میرے لیے رسوائی اور کیا ہوگی؟ اللہ تعالیٰ فرمائے گاکہ میں نے جنت کافروں پر حرام کردی ہے۔ پھر ان کے باپ کو نجاست میں لتھڑے ہوئے بجو کی شکل میں جہنم میں ڈال دیا جائے گا۔ (صحيح بخاري، سورة الشعراء وكتاب الأنبياء ، باب قول الله واتخذ الله إبراهيم خليلا)۔",
