      "en": "Do you construct on every elevation a sign,[1055] amusing yourselves,",
      "footnotesUr": "[1] رِيعٍ، رِيعَةٌ کی جمع ہے۔ ٹیلہ، بلند جگہ، پہاڑ، دریا یا گھاٹی یہ ان گزرگاہوں پر کوئی عمارت تعمیر کرتے جو ارتفاع اور علو میں ایک نشانی یعنی ممتاز ہوتی۔ لیکن اس کا مقصد اس میں رہنا نہیں ہوتا بلکہ صرف ایک کھیل کود ہوتا تھا۔ حضرت ہود (عليه السلام) نے منع فرمایا کہ یہ تم ایسا کام کرتےہو، جس میں وقت اور وسائل کا بھی ضیاع ہے اور اس کا مقصد بھی ایسا ہے جس سے دین اور دنیاکا کوئی مفاد وابستہ نہیں۔ بلکہ اس کے بیکار محض اور عبث ہونے میں کوئی شک نہیں۔",
