      "arFull": "اَتُتْرَكُوْنَ فِیْ مَا هٰهُنَاۤ اٰمِنِیْنَ ۟ۙ",
      "ur": "کیا ان چیزوں میں جو یہاں ہیں تم امن کے ساتھ چھوڑ دیے جاؤ گے.[1]",
      "en": "Will you be left in what is here, secure [from death],",
      "footnotesUr": "[1] یعنی یہ نعمتیں کیا تمہیں ہمیشہ حاصل رہیں گی، نہ تمہیں موت آئے گی نہ عذاب؟ استفہام انکاری اور تو بیخی ہے۔ یعنی ایسا نہیں ہوگا بلکہ عذاب یا موت کے ذریعے سے، جب اللہ چاہے گا، تم ان نعمتوں سے محروم ہو جاؤ گے۔ اس میں ترغیب ہے کہ اللہ کی نعمتوں کا شکر ادا کرو اور اس پر ایمان لاؤ اور ترہیب ہے کہ اگر ایمان و شکر کا راستہ اختیار نہیں کیا تو پھر تباہی و بربادی تمہارا مقدر ہے۔",
