      "en": "And fields of crops and palm trees with softened fruit?",
      "footnotesUr": "[1] یہ ان نعمتوں کی تفصیل ہے جن سے وہ بہرہ ور تھے، طلع، کھجور کے اس شگوفے کو کہتے ہیں جو پہلے پہل نکلتا یعنی طلوع ہوتا ہے، اس کے بعد کھجور کایہ پھل بلح، پھر بسر، پھر رطب اور اس کےبعد تمر کہلاتا ہے۔ (ایسر التفاسیر) باغات میں دیگر پھلوں کے ساتھ کھجور کا پھل بھی آجاتا ہے۔ لیکن عربوں میں چونکہ کھجور کی بڑی اہمیت ہے، اس لیے اس کا خصوصی طور پر بھی ذکر کیا۔ هَضِيمٌ کے اور بھی کئی معانی بیان کیے گئے ہیں۔ مثلاً لطیف اور نرم و نازک۔ تہہ بہ تہہ وغیرہ۔",
