      "arTajweed": "فَعَقَرُوهَا فَأَصْبَحُو<span class=\"tj-slnt\">ا۟</span> نَ<span class=\"tj-madda-normal\">ٰ</span>دِمِ<span class=\"tj-madda-permissible\">ي</span>نَ"
